// CONTRACT SCHEMA
/////////////////////////////////////////

export const ContractSchema = z.object({
  contractType: ContractTypeSchema,
  status: ContractStatusSchema,
  performancePeriod: PerformancePeriodSchema,
  rebatePayPeriod: PerformancePeriodSchema,
  amortizationShape: AmortizationShapeSchema,
  id: z.cuid(),
  contractNumber: z.string().nullable(),
  name: z.string(),
  vendorId: z.string(),
  facilityId: z.string().nullable(),
  productCategoryId: z.string().nullable(),
  effectiveDate: z.coerce.date(),
  expirationDate: z.coerce.date(),
  autoRenewal: z.boolean(),
  terminationNoticeDays: z.number().int(),
  totalValue: z.instanceof(PrismaDecimal, { message: "Field 'totalValue' must be a Decimal. Location: ['Models', 'Contract']"}),
  annualValue: z.instanceof(PrismaDecimal, { message: "Field 'annualValue' must be a Decimal. Location: ['Models', 'Contract']"}),
  description: z.string().nullable(),
  notes: z.string().nullable(),
  gpoAffiliation: z.string().nullable(),
  isGrouped: z.boolean(),
  additionalVendorIds: z.string().array(),
  isMultiFacility: z.boolean(),
  tieInCapitalContractId: z.string().nullable(),
  division: z.string().nullable(),
  vendorDivisionId: z.string().nullable(),
  complianceRate: z.instanceof(PrismaDecimal, { message: "Field 'complianceRate' must be a Decimal. Location: ['Models', 'Contract']"}).nullable(),
  currentMarketShare: z.instanceof(PrismaDecimal, { message: "Field 'currentMarketShare' must be a Decimal. Location: ['Models', 'Contract']"}).nullable(),
  marketShareCommitment: z.instanceof(PrismaDecimal, { message: "Field 'marketShareCommitment' must be a Decimal. Location: ['Models', 'Contract']"}).nullable(),
  /**
   * *
   * * Charles 2026-04-25 (audit follow-up): per-category market share
   * * commitments. Vendor commitments are usually expressed per
   * * category ("60% of Joint Replacement, 40% of Spine"), not as a
   * * single contract-wide number. This Json blob keeps the schema
   * * change minimal — `[{ category, commitmentPct }, ...]`.
   * * `getCategoryMarketShareForVendor` already returns the LIVE share;
   * * this stores the COMMITMENT side so the threshold engine can
   * * evaluate met-vs-target per category. Null = no per-category
   * * targets set; the engine falls back to `marketShareCommitment`
   * * (contract-wide).
   */
  marketShareCommitmentByCategory: JsonValueSchema.nullable(),
  createdById: z.string().nullable(),
  createdAt: z.coerce.date(),
  updatedAt: z.coerce.date(),
})

export type Contract = z.infer<typeof ContractSchema>

